namespace ghidra.jython;

using static org.junit.Assert;

using org.junit;

using ghidra.app.script;
using ghidra.framework.plugintool;
using ghidra.test;
using ghidra.test;

/**
 * Tests the Python Plugin functionality.
 */
public class JythonPluginTest : AbstractGhidraHeadedIntegrationTest {

	private TestEnv env;
	private PluginTool tool;
	private JythonPlugin plugin;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		tool = env.getTool();
		GhidraScriptUtil.acquireBundleHostReference();
		tool.addPlugin(typeof(JythonPlugin).getName());
		plugin = env.getPlugin(typeof(JythonPlugin));
	}

	/* @After */
	public void tearDown()
    {
		GhidraScriptUtil.releaseBundleHostReference();
		env.dispose();
	}

	/**
	 * Tests that issuing a reset from the plugin resets the interpreter.
	 */
	/* @Test */
	public void testJythonPluginReset() {
		GhidraJythonInterpreter origInterpreter = plugin.getInterpreter();
		plugin.reset();
		GhidraJythonInterpreter newInterpreter = plugin.getInterpreter();
		assertNotSame(origInterpreter, newInterpreter);
	}
}
